import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.QWVCgkrI.js";const d=JSON.parse('{"title":"プログラミング・ビルド・開発ツールの用語集","description":"","frontmatter":{"title":"プログラミング・ビルド・開発ツールの用語集","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"reference","format":"glossary","domain":"terms","summary":"プログラミング・ビルド・開発ツールで使う語の定義、用例、関連する解説記事。"}},"headers":[],"relativePath":"glossary/programming.md","filePath":"glossary/programming.md"}'),e={name:"glossary/programming.md"};function n(g,r,l,i,p,h){return a(),o("div",null,[...r[0]||(r[0]=[s('<h1 id="プログラミング・ビルド・開発ツールの用語集" tabindex="-1">プログラミング・ビルド・開発ツールの用語集 <a class="header-anchor" href="#プログラミング・ビルド・開発ツールの用語集" aria-label="Permalink to &quot;プログラミング・ビルド・開発ツールの用語集&quot;">​</a></h1><p><a href="/study/glossary/">用語集の入口・全用語検索</a></p><p>読み順で 54 項目を掲載しています。</p><h2 id="assert" tabindex="-1">アサート <a class="header-anchor" href="#assert" aria-label="Permalink to &quot;アサート {#assert}&quot;">​</a></h2><p><strong>assert / assertion</strong> ／ 読み あさーと</p><p>ここで成り立つはずの条件をコードに記述し、条件が破れた場合に検出する仕組み。</p><p><strong>この分野での意味</strong>　C++20のassertマクロはNDEBUGの設定で検査が無効になる。テストフレームワークのアサーションはテストの成否を記録する。</p><p><strong>例</strong>　添字が範囲内であることをアサートする。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/programming.html#test">テスト</a> · <a href="/study/glossary/programming.html#throw">例外を投げる</a></p><p><strong>出典</strong>　<a href="https://timsong-cpp.github.io/cppwp/n4861/assertions" target="_blank" rel="noreferrer">WG21 N4861（C++20）— Assertions</a> · <a href="https://google.github.io/googletest/primer.html" target="_blank" rel="noreferrer">GoogleTest — Primer</a></p><h2 id="incremental-build" tabindex="-1">インクリメンタルビルド <a class="header-anchor" href="#incremental-build" aria-label="Permalink to &quot;インクリメンタルビルド {#incremental-build}&quot;">​</a></h2><p><strong>incremental build</strong> ／ 読み いんくりめんたるびるど</p><p>前回の成果物を利用し、変更された入力や依存先の影響を受ける処理だけを再実行するビルド。</p><p><strong>例</strong>　ヘッダーを変更したので、それを使う翻訳単位を再コンパイルする。</p><p><strong>関連</strong>　<a href="/study/tools/build/build-speed.html">ビルド高速化</a> · <a href="/study/glossary/programming.html#clean-build">クリーンビルド</a> · <a href="/study/glossary/programming.html#build">ビルド</a></p><p><strong>出典</strong>　<a href="https://ninja-build.org/manual.html" target="_blank" rel="noreferrer">Ninja — Manual</a> · <a href="https://learn.microsoft.com/en-us/visualstudio/ide/building-and-cleaning-projects-and-solutions-in-visual-studio?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Build and clean projects and solutions</a></p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API {#api}&quot;">​</a></h2><p><strong>Application Programming Interface</strong> ／ 読み えーぴーあい</p><p>プログラムが他の部品やサービスを使うための公開された呼び出し口や取り決め。</p><p><strong>この分野での意味</strong>　関数や型を通じて使うライブラリのAPIも、通信経由で使うWeb APIもある。</p><p><strong>例</strong>　ファイルを開くOSのAPIを使う。</p><p><strong>関連</strong>　<a href="/study/compilers/libraries-apis-and-sdks.html">ライブラリ・API・SDK</a> · <a href="/study/glossary/programming.html#call-api">APIを叩く</a> · <a href="/study/glossary/programming.html#wrapper">ラッパー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/apiindex/windows-api-list" target="_blank" rel="noreferrer">Microsoft — Windows API index</a></p><h2 id="call-api" tabindex="-1">APIを叩く <a class="header-anchor" href="#call-api" aria-label="Permalink to &quot;APIを叩く {#call-api}&quot;">​</a></h2><p><strong>call an API / make an API request</strong> ／ 読み えーぴーあいをたたく</p><p>APIを呼び出すという現場の言い回し。Web APIならHTTPなどで要求を送ることを指す。</p><p><strong>例</strong>　ランキング取得APIを叩いて結果を表示する。</p><p><strong>関連</strong>　<a href="/study/compilers/libraries-apis-and-sdks.html">ライブラリ・API・SDK</a> · <a href="/study/glossary/programming.html#api">API</a></p><h2 id="enbug" tabindex="-1">エンバグ <a class="header-anchor" href="#enbug" aria-label="Permalink to &quot;エンバグ {#enbug}&quot;">​</a></h2><p><strong>introduce a bug</strong> ／ 読み えんばぐ</p><p>コードや設定を変更した結果、新しい不具合を入れてしまうことを指す現場の言い回し。</p><p><strong>例</strong>　入力処理の修正で、キーの長押しにエンバグした。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#degrade">デグレ</a> · <a href="/study/glossary/programming.html#regression">リグレッション</a></p><h2 id="crash-slang" tabindex="-1">落ちる <a class="header-anchor" href="#crash-slang" aria-label="Permalink to &quot;落ちる {#crash-slang}&quot;">​</a></h2><p><strong>crash / fail / go down</strong> ／ 読み おちる</p><p>ソフトウェアが異常終了することを指す現場の言い回し。</p><p><strong>この分野での意味</strong>　「テストが落ちる」は検査の失敗、「サーバーが落ちる」はサービスを利用できない状態を指す。原因は文脈やログから判断する。</p><p><strong>例</strong>　セーブを開くとアプリが落ちる。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#emit-log">ログを吐く</a> · <a href="/study/glossary/programming.html#test">テスト</a></p><h2 id="technical-debt" tabindex="-1">技術的負債 <a class="header-anchor" href="#technical-debt" aria-label="Permalink to &quot;技術的負債 {#technical-debt}&quot;">​</a></h2><p><strong>technical debt</strong> ／ 読み ぎじゅつてきふさい</p><p>今の実装や設計を維持すると将来の変更や保守に追加の手間がかかる状態を、借金にたとえた言い方。</p><p><strong>この分野での意味</strong>　短期の判断で意図的に持つ場合もあり、あらゆる不具合を指すわけではない。</p><p><strong>例</strong>　端末ごとの例外処理が増え、入力設定の変更に余計な確認が必要になった。</p><p><strong>関連</strong>　<a href="/study/design/foundations/tech-debt-and-refactoring.html">技術的負債とリファクタリング</a> · <a href="/study/glossary/programming.html#refactoring">リファクタリング</a></p><p><strong>出典</strong>　<a href="https://c2.com/doc/oopsla92.html" target="_blank" rel="noreferrer">Ward Cunningham — The WyCash Portfolio Management System</a> · <a href="https://refactoring.com/" target="_blank" rel="noreferrer">Martin Fowler — Refactoring</a></p><h2 id="clean-build" tabindex="-1">クリーンビルド <a class="header-anchor" href="#clean-build" aria-label="Permalink to &quot;クリーンビルド {#clean-build}&quot;">​</a></h2><p><strong>clean build</strong> ／ 読み くりーんびるど</p><p>既存の中間ファイルや出力を削除するか、空のビルド先を用意してからビルドすること。</p><p><strong>この分野での意味</strong>　依存関係やダウンロードのキャッシュまで消すかは、ツールや指定した対象による。</p><p><strong>例</strong>　古い生成コードの影響を調べるためクリーンビルドする。</p><p><strong>関連</strong>　<a href="/study/tools/build/build-speed.html">ビルド高速化</a> · <a href="/study/glossary/programming.html#incremental-build">インクリメンタルビルド</a> · <a href="/study/glossary/programming.html#rebuild">リビルド</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/visualstudio/ide/building-and-cleaning-projects-and-solutions-in-visual-studio?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Build and clean projects and solutions</a> · <a href="https://cmake.org/cmake/help/v4.3/manual/cmake.1.html" target="_blank" rel="noreferrer">CMake 4.3 — cmake(1)</a></p><h2 id="commit" tabindex="-1">コミット <a class="header-anchor" href="#commit" aria-label="Permalink to &quot;コミット {#commit}&quot;">​</a></h2><p><strong>commit</strong> ／ 読み こみっと</p><p>Gitで、その時点の変更を履歴に記録する操作。また、記録された履歴の一単位。</p><p><strong>例</strong>　描画の修正と、その確認用のテストを一つのコミットにする。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#check-in">チェックイン / サブミット</a> · <a href="/study/glossary/programming.html#branch">ブランチ</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/git-commit" target="_blank" rel="noreferrer">Git — git commit</a></p><h2 id="compile" tabindex="-1">コンパイル <a class="header-anchor" href="#compile" aria-label="Permalink to &quot;コンパイル {#compile}&quot;">​</a></h2><p><strong>compile</strong> ／ 読み こんぱいる</p><p>プログラムを、実行や後続処理に適した別の表現へ変換すること。出力は機械語、バイトコード、中間表現など処理系で異なる。</p><p><strong>この分野での意味</strong>　CやC++のツールでは、一連の変換をまとめてコンパイルと呼ぶこともある。</p><p><strong>例</strong>　player.cppをオブジェクトファイルへコンパイルする。</p><p><strong>関連</strong>　<a href="/study/tools/build/compilers.html">コンパイラの仕事</a> · <a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/programming.html#link">リンク</a> · <a href="/study/glossary/programming.html#parse">パース</a></p><p><strong>出典</strong>　<a href="https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html" target="_blank" rel="noreferrer">GCC — Options Controlling the Kind of Output</a> · <a href="https://clang.llvm.org/docs/UsersManual.html" target="_blank" rel="noreferrer">Clang — Compiler User’s Manual</a></p><h2 id="conflict" tabindex="-1">コンフリクト <a class="header-anchor" href="#conflict" aria-label="Permalink to &quot;コンフリクト {#conflict}&quot;">​</a></h2><p><strong>conflict / merge conflict</strong> ／ 読み こんふりくと</p><p>複数の変更を統合するときに、ツールが結果を自動で決められない競合。</p><p><strong>例</strong>　同じ行を別の内容に変更したため、マージでコンフリクトが起きる。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#merge">マージ</a> · <a href="/study/glossary/programming.html#diff">差分</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/git-merge" target="_blank" rel="noreferrer">Git — git merge</a></p><h2 id="diff" tabindex="-1">差分 <a class="header-anchor" href="#diff" aria-label="Permalink to &quot;差分 {#diff}&quot;">​</a></h2><p><strong>diff / difference</strong> ／ 読み さぶん / でぃふ</p><p>二つの版やファイルを比較したときに分かる変更点。また、その表示や出力を指す。</p><p><strong>例</strong>　コミット前に差分を見て、意図しない変更がないか確認する。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#patch">パッチ</a> · <a href="/study/glossary/programming.html#commit">コミット</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/git-diff" target="_blank" rel="noreferrer">Git — git diff</a></p><h2 id="ci" tabindex="-1">CI / 継続的インテグレーション <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI / 継続的インテグレーション {#ci}&quot;">​</a></h2><p><strong>Continuous Integration</strong> ／ 読み しーあい / けいぞくてきいんてぐれーしょん</p><p>変更を共有の履歴へ頻繁に統合し、ビルドやテストの自動実行で問題を早く見つける開発の進め方。</p><p><strong>この分野での意味</strong>　「CIが通る」のCIは、運用している自動チェック一式を指す。</p><p><strong>例</strong>　変更を送ったら、CIでWindows向けのビルドとテストを実行する。</p><p><strong>関連</strong>　<a href="/study/tools/ci-and-build-automation.html">CIとビルド自動化</a> · <a href="/study/glossary/programming.html#pipeline">パイプライン</a> · <a href="/study/glossary/programming.html#test">テスト</a> · <a href="/study/glossary/programming.html#build">ビルド</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/devops/develop/what-is-continuous-integration" target="_blank" rel="noreferrer">Microsoft — Continuous integration</a> · <a href="https://docs.github.com/en/actions/get-started/understand-github-actions" target="_blank" rel="noreferrer">GitHub Actions — Understanding GitHub Actions</a></p><h2 id="shim" tabindex="-1">シム <a class="header-anchor" href="#shim" aria-label="Permalink to &quot;シム {#shim}&quot;">​</a></h2><p><strong>shim</strong> ／ 読み しむ</p><p>既存コードと実行環境の間に入り、呼び出しや戻り値の変換などで互換性の差を吸収する薄い層。</p><p><strong>この分野での意味</strong>　機械のshimは隙間を調整する薄い部品。ソフトウェアでも、隙間を埋める役割を指す。</p><p><strong>例</strong>　古いツールが呼ぶAPIを新しい環境向けのシムで補う。</p><p><strong>関連</strong>　<a href="/study/design/patterns/adapter.html">Adapterパターン</a> · <a href="/study/glossary/programming.html#wrapper">ラッパー</a> · <a href="/study/glossary/programming.html#hook">フック</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/deployment/compatibility/compatibility-fixes-for-windows-8-windows-7-and-windows-vista" target="_blank" rel="noreferrer">Microsoft — Compatibility fixes</a></p><h2 id="serialize" tabindex="-1">シリアライズ <a class="header-anchor" href="#serialize" aria-label="Permalink to &quot;シリアライズ {#serialize}&quot;">​</a></h2><p><strong>serialize / serialization</strong> ／ 読み しりあらいず</p><p>データを保存・転送できるテキストやバイト列に変換すること。変換した表現からデータを取り出す操作をデシリアライズと呼ぶ。</p><p><strong>この分野での意味</strong>　処理を並列に進めず順番に実行することも、英語ではserializeと呼ぶ。</p><p><strong>例</strong>　プレイヤーの進行状況をJSONにシリアライズする。</p><p><strong>関連</strong>　<a href="/study/game/basics/save-data-and-serialization.html">セーブデータとシリアライズ</a> · <a href="/study/glossary/programming.html#marshalling">マーシャリング</a> · <a href="/study/glossary/programming.html#parse">パース</a></p><p><strong>出典</strong>　<a href="https://protobuf.dev/programming-guides/encoding/" target="_blank" rel="noreferrer">Protocol Buffers — Encoding</a></p><h2 id="stack" tabindex="-1">スタック <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;スタック {#stack}&quot;">​</a></h2><p><strong>stack / call stack</strong> ／ 読み すたっく</p><p>関数の呼び出しに伴う情報を積み、内側の呼び出しから順に取り除く仕組み。また、そのためのメモリ領域。</p><p><strong>この分野での意味</strong>　データ構造のスタックは後入れ先出しの入れ物。「技術スタック」は使う技術群を指す。</p><p><strong>例</strong>　再帰が深くなり、スレッドのスタックを使い切った。</p><p><strong>関連</strong>　<a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出しとCPU</a> · <a href="/study/algorithms/queues-and-deques.html">スタック・キュー・デック</a> · <a href="/study/glossary/programming.html#stack-frame">スタックフレーム</a> · <a href="/study/glossary/programming.html#heap">ヒープ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/cpp/build/stack-usage?view=msvc-170" target="_blank" rel="noreferrer">Microsoft — x64 stack usage</a> · <a href="https://learn.microsoft.com/en-us/visualstudio/debugger/how-to-use-the-call-stack-window?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Call Stack window</a></p><h2 id="stack-frame" tabindex="-1">スタックフレーム <a class="header-anchor" href="#stack-frame" aria-label="Permalink to &quot;スタックフレーム {#stack-frame}&quot;">​</a></h2><p><strong>stack frame / activation record</strong> ／ 読み すたっくふれーむ</p><p>一回の関数呼び出しに対応する実行情報のまとまり。呼び出し規約や最適化によって、戻り先、退避したレジスター、局所データなどの配置が変わる。</p><p><strong>この分野での意味</strong>　ここでのフレームは関数呼び出しの単位。描画や通信にも、それぞれ別のフレームがある。</p><p><strong>例</strong>　デバッガーで呼び出し元のスタックフレームを選ぶ。</p><p><strong>関連</strong>　<a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出しとCPU</a> · <a href="/study/glossary/programming.html#stack">スタック</a> · <a href="/study/glossary/programming.html#debugger">デバッガー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/cpp/build/stack-usage?view=msvc-170" target="_blank" rel="noreferrer">Microsoft — x64 stack usage</a> · <a href="https://learn.microsoft.com/en-us/visualstudio/debugger/how-to-use-the-call-stack-window?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Call Stack window</a></p><h2 id="stub" tabindex="-1">スタブ <a class="header-anchor" href="#stub" aria-label="Permalink to &quot;スタブ {#stub}&quot;">​</a></h2><p><strong>stub / test stub</strong> ／ 読み すたぶ</p><p>テスト対象から呼ばれたときに、あらかじめ決めた値や応答を返す代役。</p><p><strong>この分野での意味</strong>　未実装の関数を仮につなぐ短い実装や、別プロセスに呼び出しを中継するコードもスタブと呼ばれる。</p><p><strong>例</strong>　時刻を取得する関数を、決まった時刻を返すスタブにする。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#test-double">テストダブル</a> · <a href="/study/glossary/programming.html#mock">モック</a> · <a href="/study/glossary/programming.html#trampoline">トランポリン</a></p><p><strong>出典</strong>　<a href="https://martinfowler.com/bliki/TestDouble.html" target="_blank" rel="noreferrer">Martin Fowler — Test Double</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/rpc/how-rpc-works" target="_blank" rel="noreferrer">Microsoft — How Remote Procedure Call (RPC) works</a></p><h2 id="spy" tabindex="-1">スパイ <a class="header-anchor" href="#spy" aria-label="Permalink to &quot;スパイ {#spy}&quot;">​</a></h2><p><strong>spy / test spy</strong> ／ 読み すぱい</p><p>実際に呼ばれた回数や引数などを記録し、テストの後から確認できるようにする代役。</p><p><strong>例</strong>　通知先にスパイを渡し、記録したイベントを検査する。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#test-double">テストダブル</a> · <a href="/study/glossary/programming.html#mock">モック</a></p><p><strong>出典</strong>　<a href="https://martinfowler.com/articles/mocksArentStubs.html" target="_blank" rel="noreferrer">Martin Fowler — Mocks Aren’t Stubs</a></p><h2 id="dirty" tabindex="-1">ダーティ <a class="header-anchor" href="#dirty" aria-label="Permalink to &quot;ダーティ {#dirty}&quot;">​</a></h2><p><strong>dirty / dirty flag</strong> ／ 読み だーてぃ</p><p>変更が発生し、保存・再計算・再描画などの反映がまだ済んでいない状態。</p><p><strong>この分野での意味</strong>　Gitのdirtyな作業ツリーは未コミットの変更がある状態。再計算用のダーティフラグは、更新が必要な対象を記録する。</p><p><strong>例</strong>　親の位置を変更したら、子のワールド行列をダーティにする。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#flag">フラグ</a> · <a href="/study/glossary/programming.html#commit">コミット</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/gitglossary" target="_blank" rel="noreferrer">Git — Git Glossary</a> · <a href="https://learn.microsoft.com/en-us/dotnet/api/system.windows.uielement.invalidatevisual?view=windowsdesktop-10.0" target="_blank" rel="noreferrer">Microsoft — WPF UIElement.InvalidateVisual</a></p><h2 id="dangling" tabindex="-1">ダングリング <a class="header-anchor" href="#dangling" aria-label="Permalink to &quot;ダングリング {#dangling}&quot;">​</a></h2><p><strong>dangling pointer / dangling reference</strong> ／ 読み だんぐりんぐ</p><p>ポインターや参照などが、すでに寿命の終わった対象を指したままになっている状態。</p><p><strong>例</strong>　破棄済みの敵を指すダングリングポインターが更新リストに残る。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/memory-bugs.html">メモリのバグ</a> · <a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間・スコープ・寿命</a> · <a href="/study/glossary/programming.html#heap">ヒープ</a> · <a href="/study/glossary/programming.html#leak">リーク</a></p><p><strong>出典</strong>　<a href="https://timsong-cpp.github.io/cppwp/n4861/basic.life" target="_blank" rel="noreferrer">WG21 N4861（C++20）— Object lifetime</a> · <a href="https://clang.llvm.org/docs/AddressSanitizer.html" target="_blank" rel="noreferrer">Clang — AddressSanitizer</a></p><h2 id="check-in" tabindex="-1">チェックイン / サブミット <a class="header-anchor" href="#check-in" aria-label="Permalink to &quot;チェックイン / サブミット {#check-in}&quot;">​</a></h2><p><strong>check in / submit</strong> ／ 読み ちぇっくいん / さぶみっと</p><p>バージョン管理へ変更を登録すること。Perforce P4のsubmitは、変更リストをサーバーのdepotへ登録する。</p><p><strong>この分野での意味</strong>　登録の範囲はツールによる。Gitでは履歴を記録するcommitと、リモートに反映するpushが別の操作。</p><p><strong>例</strong>　修正したアセットとコードを同じ変更リストでサブミットする。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#commit">コミット</a> · <a href="/study/glossary/programming.html#branch">ブランチ</a></p><p><strong>出典</strong>　<a href="https://help.perforce.com/helix-core/server-apps/cmdref/current/Content/CmdRef/p4_submit.html" target="_blank" rel="noreferrer">Perforce P4 — p4 submit</a> · <a href="https://git-scm.com/docs/git-commit" target="_blank" rel="noreferrer">Git — git commit</a> · <a href="https://git-scm.com/docs/gitglossary" target="_blank" rel="noreferrer">Git — Git Glossary</a></p><h2 id="degrade" tabindex="-1">デグレ <a class="header-anchor" href="#degrade" aria-label="Permalink to &quot;デグレ {#degrade}&quot;">​</a></h2><p><strong>regression / degradation</strong> ／ 読み でぐれ</p><p>変更後に、以前はできたことができなくなったり、性能や品質が以前より悪化したりすることを指す現場の言い回し。</p><p><strong>例</strong>　メニューの修正後、ゲームパッドでの操作がデグレした。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#enbug">エンバグ</a> · <a href="/study/glossary/programming.html#regression">リグレッション</a></p><h2 id="test" tabindex="-1">テスト <a class="header-anchor" href="#test" aria-label="Permalink to &quot;テスト {#test}&quot;">​</a></h2><p><strong>test / software test</strong> ／ 読み てすと</p><p>入力と条件を決め、ソフトウェアの出力や振る舞いが期待に合うか確かめること。</p><p><strong>例</strong>　HPが0になったときにゲームオーバーへ移るかをテストする。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/programming.html#test-double">テストダブル</a> · <a href="/study/glossary/programming.html#assert">アサート</a> · <a href="/study/glossary/programming.html#regression">リグレッション</a></p><p><strong>出典</strong>　<a href="https://google.github.io/googletest/primer.html" target="_blank" rel="noreferrer">GoogleTest — Primer</a></p><h2 id="test-double" tabindex="-1">テストダブル <a class="header-anchor" href="#test-double" aria-label="Permalink to &quot;テストダブル {#test-double}&quot;">​</a></h2><p><strong>test double</strong> ／ 読み てすとだぶる</p><p>テスト時に本物の依存先と差し替えて使う代役の総称。スタブ、モック、フェイク、スパイなどがある。</p><p><strong>例</strong>　通信を伴わずに確認できるよう、サーバーへの依存をテストダブルに差し替える。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/programming.html#stub">スタブ</a> · <a href="/study/glossary/programming.html#mock">モック</a> · <a href="/study/glossary/programming.html#fake">フェイク</a> · <a href="/study/glossary/programming.html#spy">スパイ</a></p><p><strong>出典</strong>　<a href="https://martinfowler.com/bliki/TestDouble.html" target="_blank" rel="noreferrer">Martin Fowler — Test Double</a></p><h2 id="debugger" tabindex="-1">デバッガー <a class="header-anchor" href="#debugger" aria-label="Permalink to &quot;デバッガー {#debugger}&quot;">​</a></h2><p><strong>debugger</strong> ／ 読み でばがー</p><p>プログラムの実行を止め、命令の進行、変数、スレッド、呼び出し履歴などを調べる道具。</p><p><strong>例</strong>　デバッガーでHPが書き換わる直前に実行を止める。</p><p><strong>関連</strong>　<a href="/study/tools/windows/debugger-breakpoints-and-watchpoints.html">ブレークポイントとデータブレークポイント</a> · <a href="/study/glossary/programming.html#stack-frame">スタックフレーム</a> · <a href="/study/glossary/programming.html#emit-log">ログを吐く</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/visualstudio/debugger/how-to-use-the-call-stack-window?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Call Stack window</a></p><h2 id="deploy" tabindex="-1">デプロイ <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;デプロイ {#deploy}&quot;">​</a></h2><p><strong>deploy / deployment</strong> ／ 読み でぷろい</p><p>作ったソフトウェアや設定を、実際に動かす環境へ配置して使える状態にすること。</p><p><strong>この分野での意味</strong>　テスト環境への配置もデプロイと呼ぶ。利用者への公開を伴うかは環境と運用で決まる。</p><p><strong>例</strong>　修正版をステージング環境へデプロイする。</p><p><strong>関連</strong>　<a href="/study/tools/ci-and-build-automation.html">CIとビルド自動化</a> · <a href="/study/glossary/programming.html#release">リリース</a> · <a href="/study/glossary/programming.html#pipeline">パイプライン</a></p><p><strong>出典</strong>　<a href="https://docs.github.com/en/actions/how-tos/deploy/configure-and-manage-deployments/control-deployments" target="_blank" rel="noreferrer">GitHub Actions — Control deployments</a></p><h2 id="trampoline" tabindex="-1">トランポリン <a class="header-anchor" href="#trampoline" aria-label="Permalink to &quot;トランポリン {#trampoline}&quot;">​</a></h2><p><strong>trampoline</strong> ／ 読み とらんぽりん</p><p>本来の処理へジャンプする前に経由する小さな中継コード。呼び出し先が必要とする情報の設定を受け持つことがある。</p><p><strong>この分野での意味</strong>　GCCの入れ子関数では、対象によって外側の文脈を渡してから本体へジャンプする中継が使われる。</p><p><strong>例</strong>　入れ子関数のアドレスを呼ぶと、トランポリンが外側の文脈をセットする。</p><p><strong>関連</strong>　<a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出しとCPU</a> · <a href="/study/glossary/programming.html#stub">スタブ</a> · <a href="/study/glossary/programming.html#stack-frame">スタックフレーム</a></p><p><strong>出典</strong>　<a href="https://gcc.gnu.org/onlinedocs/gccint/Trampolines.html" target="_blank" rel="noreferrer">GCC Internals — Trampolines</a></p><h2 id="parse" tabindex="-1">パース <a class="header-anchor" href="#parse" aria-label="Permalink to &quot;パース {#parse}&quot;">​</a></h2><p><strong>parse / parsing</strong> ／ 読み ぱーす</p><p>入力の記述を文法や形式に従って解析し、その構造を読み取ること。</p><p><strong>この分野での意味</strong>　コンパイラでは、字句解析で作ったトークン列から式や文の構造を調べる段階を指す。</p><p><strong>例</strong>　設定ファイルをパースしてキーと値を取り出す。</p><p><strong>関連</strong>　<a href="/study/compilers/tokens-ast-and-type-checking.html">トークン・AST・型検査</a> · <a href="/study/glossary/programming.html#compile">コンパイル</a> · <a href="/study/glossary/programming.html#serialize">シリアライズ</a></p><p><strong>出典</strong>　<a href="https://clang.llvm.org/docs/InternalsManual.html#the-parser-library" target="_blank" rel="noreferrer">Clang — The Parser Library</a></p><h2 id="pipeline" tabindex="-1">パイプライン <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;パイプライン {#pipeline}&quot;">​</a></h2><p><strong>pipeline</strong> ／ 読み ぱいぷらいん</p><p>成果や処理を受け渡す工程のつながり。CI/CDではビルド、テスト、配布先への反映などを順に、または依存に応じて実行する。</p><p><strong>この分野での意味</strong>　GPUの描画パイプラインは、頂点などの入力から画面の出力を作る処理段階を指す。</p><p><strong>例</strong>　テストに通った成果物だけをデプロイするパイプラインを組む。</p><p><strong>関連</strong>　<a href="/study/tools/ci-and-build-automation.html">CIとビルド自動化</a> · <a href="/study/glossary/programming.html#ci">CI / 継続的インテグレーション</a> · <a href="/study/glossary/programming.html#deploy">デプロイ</a></p><p><strong>出典</strong>　<a href="https://docs.github.com/en/actions/get-started/understand-github-actions" target="_blank" rel="noreferrer">GitHub Actions — Understanding GitHub Actions</a></p><h2 id="patch" tabindex="-1">パッチ <a class="header-anchor" href="#patch" aria-label="Permalink to &quot;パッチ {#patch}&quot;">​</a></h2><p><strong>patch</strong> ／ 読み ぱっち</p><p>既存のソフトウェアやデータに適用する変更。ソース管理では、適用できる形式で書き出した差分を指すことがある。</p><p><strong>この分野での意味</strong>　配信では、修正版の更新データや小規模な更新版もパッチと呼ぶ。</p><p><strong>例</strong>　不具合を直すパッチを保守ブランチにも適用する。</p><p><strong>関連</strong>　<a href="/study/game/asset-build-and-patches.html">ゲームのアセットビルドと差分配布</a> · <a href="/study/glossary/programming.html#diff">差分</a> · <a href="/study/glossary/programming.html#monkey-patch">モンキーパッチ</a> · <a href="/study/glossary/programming.html#release">リリース</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/git-apply" target="_blank" rel="noreferrer">Git — git apply</a></p><h2 id="heap" tabindex="-1">ヒープ <a class="header-anchor" href="#heap" aria-label="Permalink to &quot;ヒープ {#heap}&quot;">​</a></h2><p><strong>heap / dynamic memory heap</strong> ／ 読み ひーぷ</p><p>実行時の要求に応じて領域を確保し、不要になった領域を解放・再利用するメモリ管理の領域。</p><p><strong>この分野での意味</strong>　アルゴリズムのヒープは、親子間の順序を保つデータ構造を指す。</p><p><strong>例</strong>　ロードしたデータ用の領域をヒープから確保する。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/allocation-journey.html">メモリ確保の内部</a> · <a href="/study/algorithms/binary-heaps.html">二分ヒープと優先度付きキュー</a> · <a href="/study/glossary/programming.html#stack">スタック</a> · <a href="/study/glossary/programming.html#leak">リーク</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/memory/heap-functions" target="_blank" rel="noreferrer">Microsoft — Heap Functions</a></p><h2 id="build" tabindex="-1">ビルド <a class="header-anchor" href="#build" aria-label="Permalink to &quot;ビルド {#build}&quot;">​</a></h2><p><strong>build</strong> ／ 読み びるど</p><p>ソースや素材から実行ファイルなどの成果物を作る工程。構成によってはコード生成、コンパイル、リンク、パッケージ化まで含む。</p><p><strong>この分野での意味</strong>　「最新ビルドを試す」のように、出来上がった成果物や版を指すこともある。</p><p><strong>例</strong>　Windows向けのRelease構成でビルドする。</p><p><strong>関連</strong>　<a href="/study/tools/build/what-is-build.html">ビルドとは何か</a> · <a href="/study/glossary/programming.html#compile">コンパイル</a> · <a href="/study/glossary/programming.html#link">リンク</a> · <a href="/study/glossary/programming.html#artifact">ビルド成果物</a></p><p><strong>出典</strong>　<a href="https://cmake.org/cmake/help/v4.3/manual/cmake.1.html" target="_blank" rel="noreferrer">CMake 4.3 — cmake(1)</a> · <a href="https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html" target="_blank" rel="noreferrer">GCC — Options Controlling the Kind of Output</a></p><h2 id="artifact" tabindex="-1">ビルド成果物 <a class="header-anchor" href="#artifact" aria-label="Permalink to &quot;ビルド成果物 {#artifact}&quot;">​</a></h2><p><strong>build artifact</strong> ／ 読み びるどせいかぶつ</p><p>ビルドや自動処理が作ったファイル。実行ファイル、配布パッケージ、デバッグ情報などを指す。</p><p><strong>この分野での意味</strong>　CIではテスト結果やログも、実行後に取り出せる成果物として保存することがある。</p><p><strong>例</strong>　CIで作った実行ファイルとデバッグ情報を保存する。</p><p><strong>関連</strong>　<a href="/study/tools/ci-and-build-automation.html">CIとビルド自動化</a> · <a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/programming.html#pipeline">パイプライン</a></p><p><strong>出典</strong>　<a href="https://docs.github.com/en/actions/concepts/workflows-and-actions/workflow-artifacts" target="_blank" rel="noreferrer">GitHub Actions — Workflow artifacts</a></p><h2 id="run-build" tabindex="-1">ビルドを回す <a class="header-anchor" href="#run-build" aria-label="Permalink to &quot;ビルドを回す {#run-build}&quot;">​</a></h2><p><strong>run a build</strong> ／ 読み びるどをまわす</p><p>ビルドを実行して成果物や結果を確認できる状態にする、という開発現場の言い回し。</p><p><strong>例</strong>　修正を取り込んだら、もう一度ビルドを回す。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/programming.html#ci">CI / 継続的インテグレーション</a></p><h2 id="fake" tabindex="-1">フェイク <a class="header-anchor" href="#fake" aria-label="Permalink to &quot;フェイク {#fake}&quot;">​</a></h2><p><strong>fake / fake object</strong> ／ 読み ふぇいく</p><p>実際に処理できる簡易実装を使い、本物の依存先を置き換えるテスト用の代役。</p><p><strong>例</strong>　データベースのフェイクをメモリ上の連想配列で実装する。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#test-double">テストダブル</a> · <a href="/study/glossary/programming.html#stub">スタブ</a></p><p><strong>出典</strong>　<a href="https://martinfowler.com/bliki/TestDouble.html" target="_blank" rel="noreferrer">Martin Fowler — Test Double</a> · <a href="https://google.github.io/googletest/gmock_for_dummies.html" target="_blank" rel="noreferrer">GoogleTest — gMock for Dummies</a></p><h2 id="hook" tabindex="-1">フック <a class="header-anchor" href="#hook" aria-label="Permalink to &quot;フック {#hook}&quot;">​</a></h2><p><strong>hook</strong> ／ 読み ふっく</p><p>処理の決まった地点で、利用側が登録した処理を呼べるようにする仕組み。また、登録した処理そのもの。</p><p><strong>この分野での意味</strong>　既存の呼び出しへ処理を差し込むことも「フックする」と呼ぶ。利用できる仕組みや呼ばれる時点は環境による。</p><p><strong>例</strong>　コミット前のフックで整形結果を確認する。</p><p><strong>関連</strong>　<a href="/study/design/patterns/template-method.html">Template Methodパターン</a> · <a href="/study/glossary/programming.html#wrapper">ラッパー</a> · <a href="/study/glossary/programming.html#shim">シム</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/githooks" target="_blank" rel="noreferrer">Git — githooks</a></p><h2 id="flag" tabindex="-1">フラグ <a class="header-anchor" href="#flag" aria-label="Permalink to &quot;フラグ {#flag}&quot;">​</a></h2><p><strong>flag</strong> ／ 読み ふらぐ</p><p>状態や機能の有無を示す値。複数の独立した状態を整数のビットで表すこともある。</p><p><strong>この分野での意味</strong>　コマンドの「フラグ」は、機能や動作を指定するコマンドラインオプションを指す。</p><p><strong>例</strong>　デバッグ表示を有効にするフラグを立てる。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#dirty">ダーティ</a> · <a href="/study/glossary/programming.html#compile">コンパイル</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/dotnet/api/system.flagsattribute?view=net-10.0" target="_blank" rel="noreferrer">.NET 10 — FlagsAttribute</a> · <a href="https://clang.llvm.org/docs/UsersManual.html" target="_blank" rel="noreferrer">Clang — Compiler User’s Manual</a></p><h2 id="branch" tabindex="-1">ブランチ <a class="header-anchor" href="#branch" aria-label="Permalink to &quot;ブランチ {#branch}&quot;">​</a></h2><p><strong>branch</strong> ／ 読み ぶらんち</p><p>バージョン管理で、変更を別の流れとして進めるための分岐。Gitのブランチ名は履歴の先端のコミットを指す。</p><p><strong>この分野での意味</strong>　プログラムやCPUでbranchと言うと、実行する経路を切り替える分岐を指す。</p><p><strong>例</strong>　敵の行動を修正する作業用ブランチを作る。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#commit">コミット</a> · <a href="/study/glossary/programming.html#merge">マージ</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/gitglossary" target="_blank" rel="noreferrer">Git — Git Glossary</a></p><h2 id="boilerplate" tabindex="-1">ボイラープレート <a class="header-anchor" href="#boilerplate" aria-label="Permalink to &quot;ボイラープレート {#boilerplate}&quot;">​</a></h2><p><strong>boilerplate / boilerplate code</strong> ／ 読み ぼいらーぷれーと</p><p>同種のファイルやプロジェクトで繰り返し使う定型コード。初期化や登録などの共通部分を指す。</p><p><strong>例</strong>　プロジェクト生成コマンドで初期化のボイラープレートを用意する。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/programming.html#refactoring">リファクタリング</a></p><p><strong>出典</strong>　<a href="https://doc.rust-lang.org/cargo/commands/cargo-new.html" target="_blank" rel="noreferrer">Cargo — cargo new</a></p><h2 id="hot-reload" tabindex="-1">ホットリロード <a class="header-anchor" href="#hot-reload" aria-label="Permalink to &quot;ホットリロード {#hot-reload}&quot;">​</a></h2><p><strong>hot reload</strong> ／ 読み ほっとりろーど</p><p>アプリや開発環境を再起動せず、実行中にコードやデータの変更を反映すること。</p><p><strong>この分野での意味</strong>　どの変更を反映できるか、既存の状態がどこまで残るかは実装や編集内容で変わる。</p><p><strong>例</strong>　プレイ中のままUIの変更をホットリロードする。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#build">ビルド</a> · <a href="/study/glossary/programming.html#debugger">デバッガー</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/visualstudio/debugger/hot-reload?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Hot Reload</a></p><h2 id="merge" tabindex="-1">マージ <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;マージ {#merge}&quot;">​</a></h2><p><strong>merge</strong> ／ 読み まーじ</p><p>バージョン管理で、別々の履歴にある変更を統合すること。</p><p><strong>この分野での意味</strong>　Gitでは統合の形によって、マージコミットを作る場合と、ブランチの参照先を進める場合がある。</p><p><strong>例</strong>　レビュー済みの変更をメインブランチにマージする。</p><p><strong>関連</strong>　<a href="/study/tools/git-basics.html">Gitの基本</a> · <a href="/study/glossary/programming.html#branch">ブランチ</a> · <a href="/study/glossary/programming.html#conflict">コンフリクト</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/gitglossary" target="_blank" rel="noreferrer">Git — Git Glossary</a> · <a href="https://git-scm.com/docs/git-merge" target="_blank" rel="noreferrer">Git — git merge</a></p><h2 id="marshalling" tabindex="-1">マーシャリング <a class="header-anchor" href="#marshalling" aria-label="Permalink to &quot;マーシャリング {#marshalling}&quot;">​</a></h2><p><strong>marshal / marshalling</strong> ／ 読み まーしゃりんぐ</p><p>言語やプロセスなどの境界を越えて値を渡せるよう、型や表現を受け渡し先に合わせる処理。</p><p><strong>この分野での意味</strong>　シリアライズを含む場合もある。.NETとネイティブコードの相互運用では、文字列の表現や構造体の配置などの変換を指す。</p><p><strong>例</strong>　C#の文字列をネイティブAPIが要求する表現にマーシャリングする。</p><p><strong>関連</strong>　<a href="/study/compilers/libraries-apis-and-sdks.html">ライブラリ・API・SDK</a> · <a href="/study/glossary/programming.html#serialize">シリアライズ</a> · <a href="/study/glossary/programming.html#api">API</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/dotnet/standard/native-interop/type-marshalling" target="_blank" rel="noreferrer">.NET — Type marshalling</a></p><h2 id="mock" tabindex="-1">モック <a class="header-anchor" href="#mock" aria-label="Permalink to &quot;モック {#mock}&quot;">​</a></h2><p><strong>mock / mock object</strong> ／ 読み もっく</p><p>期待する呼び出し、引数、回数などを設定し、実際のやり取りが期待どおりか確かめるテスト用の代役。</p><p><strong>この分野での意味</strong>　画面設計で「モック」と言う場合は、操作や見た目を試すための模型を指すことがある。</p><p><strong>例</strong>　セーブを1回だけ要求したか、保存先のモックで確かめる。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#test-double">テストダブル</a> · <a href="/study/glossary/programming.html#stub">スタブ</a> · <a href="/study/glossary/programming.html#spy">スパイ</a></p><p><strong>出典</strong>　<a href="https://martinfowler.com/bliki/TestDouble.html" target="_blank" rel="noreferrer">Martin Fowler — Test Double</a> · <a href="https://google.github.io/googletest/gmock_for_dummies.html" target="_blank" rel="noreferrer">GoogleTest — gMock for Dummies</a></p><h2 id="monkey-patch" tabindex="-1">モンキーパッチ <a class="header-anchor" href="#monkey-patch" aria-label="Permalink to &quot;モンキーパッチ {#monkey-patch}&quot;">​</a></h2><p><strong>monkey patch</strong> ／ 読み もんきーぱっち</p><p>実行時に既存のモジュールやオブジェクトの属性・関数を差し替えて振る舞いを変えること。</p><p><strong>この分野での意味</strong>　テスト中だけ一時的に差し替える用途もある。どの名前を変更すると呼び出し側に効くかは、参照の取り方で決まる。</p><p><strong>例</strong>　テスト中だけ時刻取得関数を差し替える。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#patch">パッチ</a> · <a href="/study/glossary/programming.html#stub">スタブ</a> · <a href="/study/glossary/programming.html#hook">フック</a></p><p><strong>出典</strong>　<a href="https://docs.python.org/3/library/unittest.mock.html#unittest.mock.patch" target="_blank" rel="noreferrer">Python — unittest.mock.patch</a></p><h2 id="wrapper" tabindex="-1">ラッパー <a class="header-anchor" href="#wrapper" aria-label="Permalink to &quot;ラッパー {#wrapper}&quot;">​</a></h2><p><strong>wrapper</strong> ／ 読み らっぱー</p><p>既存の関数やオブジェクトを包み、呼び出しを委譲する関数や型。変換やログ記録などの処理を加えることもできる。</p><p><strong>例</strong>　ファイルAPIのラッパーで失敗時のログをそろえる。</p><p><strong>関連</strong>　<a href="/study/design/patterns/decorator.html">Decoratorパターン</a> · <a href="/study/glossary/programming.html#shim">シム</a> · <a href="/study/glossary/programming.html#hook">フック</a></p><p><strong>出典</strong>　<a href="https://docs.python.org/3/library/functools.html#functools.wraps" target="_blank" rel="noreferrer">Python — functools.wraps</a></p><h2 id="leak" tabindex="-1">リーク <a class="header-anchor" href="#leak" aria-label="Permalink to &quot;リーク {#leak}&quot;">​</a></h2><p><strong>leak / memory leak / resource leak</strong> ／ 読み りーく</p><p>使い終えたメモリやリソースが解放されず、占有が続くこと。</p><p><strong>この分野での意味</strong>　ゲームの告知前情報が漏れる「リーク」とは区別する。メモリの例では、参照が残って回収されない場合もある。</p><p><strong>例</strong>　シーンを開き直すたびにテクスチャがリークしてメモリ使用量が増える。</p><p><strong>関連</strong>　<a href="/study/runtime/memory/memory-bugs.html">メモリのバグ</a> · <a href="/study/glossary/programming.html#heap">ヒープ</a> · <a href="/study/glossary/programming.html#dangling">ダングリング</a></p><p><strong>出典</strong>　<a href="https://clang.llvm.org/docs/LeakSanitizer.html" target="_blank" rel="noreferrer">Clang — LeakSanitizer</a></p><h2 id="regression" tabindex="-1">リグレッション <a class="header-anchor" href="#regression" aria-label="Permalink to &quot;リグレッション {#regression}&quot;">​</a></h2><p><strong>regression / software regression</strong> ／ 読み りぐれっしょん</p><p>変更によって、以前動いていた機能や満たしていた性能・品質が悪化すること。</p><p><strong>この分野での意味</strong>　回帰テストは以前の振る舞いが保たれるかを検査する。統計学の「回帰」は、変数どうしの関係をモデル化する別の用法。</p><p><strong>例</strong>　描画負荷のリグレッションを前のビルドと比較する。</p><p><strong>関連</strong>　<a href="/study/tools/automated-testing.html">自動テストの基礎</a> · <a href="/study/glossary/programming.html#degrade">デグレ</a> · <a href="/study/glossary/programming.html#test">テスト</a></p><p><strong>出典</strong>　<a href="https://git-scm.com/docs/git-bisect" target="_blank" rel="noreferrer">Git — git bisect</a> · <a href="https://www.itl.nist.gov/div898/handbook/pmd/section1/pmd141.htm" target="_blank" rel="noreferrer">NIST — What is regression?</a></p><h2 id="rebuild" tabindex="-1">リビルド <a class="header-anchor" href="#rebuild" aria-label="Permalink to &quot;リビルド {#rebuild}&quot;">​</a></h2><p><strong>rebuild</strong> ／ 読み りびるど</p><p>成果物を作り直すこと。Visual Studio 2022の「リビルド」は、選んだ対象をクリーンにしてからビルドする操作。</p><p><strong>この分野での意味</strong>　「リビルドして」は単にビルドを再実行する意味でも使う。対象や消す範囲は操作名とツールによる。</p><p><strong>例</strong>　構成を切り替えてソリューションをリビルドする。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#clean-build">クリーンビルド</a> · <a href="/study/glossary/programming.html#incremental-build">インクリメンタルビルド</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/visualstudio/ide/building-and-cleaning-projects-and-solutions-in-visual-studio?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Build and clean projects and solutions</a></p><h2 id="refactoring" tabindex="-1">リファクタリング <a class="header-anchor" href="#refactoring" aria-label="Permalink to &quot;リファクタリング {#refactoring}&quot;">​</a></h2><p><strong>refactor / refactoring</strong> ／ 読み りふぁくたりんぐ</p><p>外から観察できる振る舞いを保ったまま、コードの内部構造を改善すること。</p><p><strong>例</strong>　同じ計算を一つの関数にまとめ、変更前と同じ結果をテストする。</p><p><strong>関連</strong>　<a href="/study/design/foundations/tech-debt-and-refactoring.html">技術的負債とリファクタリング</a> · <a href="/study/guide/cpp-glossary.html">C++・設計の用語集</a> · <a href="/study/glossary/programming.html#technical-debt">技術的負債</a> · <a href="/study/glossary/programming.html#regression">リグレッション</a></p><p><strong>出典</strong>　<a href="https://refactoring.com/" target="_blank" rel="noreferrer">Martin Fowler — Refactoring</a></p><h2 id="release" tabindex="-1">リリース <a class="header-anchor" href="#release" aria-label="Permalink to &quot;リリース {#release}&quot;">​</a></h2><p><strong>release</strong> ／ 読み りりーす</p><p>特定の版を利用者や配布先が使えるようにすること。また、その公開版を指す。</p><p><strong>この分野での意味</strong>　Releaseビルドの「Release」は構成名。最適化の設定と配布の可否はそれぞれ決まる。</p><p><strong>例</strong>　バージョン1.2をリリースし、変更点を公開する。</p><p><strong>関連</strong>　<a href="/study/tools/build/build-configurations.html">ビルド構成とデバッグ情報</a> · <a href="/study/glossary/programming.html#deploy">デプロイ</a> · <a href="/study/glossary/programming.html#patch">パッチ</a></p><p><strong>出典</strong>　<a href="https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases" target="_blank" rel="noreferrer">GitHub Docs — About releases</a> · <a href="https://learn.microsoft.com/en-us/visualstudio/ide/building-and-cleaning-projects-and-solutions-in-visual-studio?view=vs-2022" target="_blank" rel="noreferrer">Visual Studio 2022 — Build and clean projects and solutions</a></p><h2 id="link" tabindex="-1">リンク <a class="header-anchor" href="#link" aria-label="Permalink to &quot;リンク {#link}&quot;">​</a></h2><p><strong>link / linking</strong> ／ 読み りんく</p><p>オブジェクトファイルやライブラリのシンボル参照を解決し、実行ファイルやライブラリなどへまとめる処理。</p><p><strong>この分野での意味</strong>　この文脈では、Webページ間のリンクや資料への参照とは別の処理を指す。</p><p><strong>例</strong>　入力モジュールと描画モジュールをリンクする。</p><p><strong>関連</strong>　<a href="/study/tools/build/link-errors.html">リンクエラー</a> · <a href="/study/runtime/cpp-internals/object-files-and-libraries.html">オブジェクトファイルとライブラリ</a> · <a href="/study/glossary/programming.html#compile">コンパイル</a> · <a href="/study/glossary/programming.html#build">ビルド</a></p><p><strong>出典</strong>　<a href="https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html" target="_blank" rel="noreferrer">GCC — Options Controlling the Kind of Output</a></p><h2 id="throw" tabindex="-1">例外を投げる <a class="header-anchor" href="#throw" aria-label="Permalink to &quot;例外を投げる {#throw}&quot;">​</a></h2><p><strong>throw an exception</strong> ／ 読み れいがいをなげる</p><p>例外を発生させ、通常の処理の流れから、対応する例外ハンドラーを探す処理へ移ること。</p><p><strong>例</strong>　想定していない形式のデータを受け取ったら例外を投げる。</p><p><strong>関連</strong>　<a href="/study/languages/cpp/exceptions.html">C++の例外</a> · <a href="/study/languages/csharp/exceptions-comparison.html">C++例外とC#例外</a> · <a href="/study/glossary/programming.html#crash-slang">落ちる</a> · <a href="/study/glossary/programming.html#assert">アサート</a></p><p><strong>出典</strong>　<a href="https://timsong-cpp.github.io/cppwp/n4861/except.throw" target="_blank" rel="noreferrer">WG21 N4861（C++20）— Throwing an exception</a></p><h2 id="emit-log" tabindex="-1">ログを吐く <a class="header-anchor" href="#emit-log" aria-label="Permalink to &quot;ログを吐く {#emit-log}&quot;">​</a></h2><p><strong>emit a log / write a log</strong> ／ 読み ろぐをはく</p><p>実行時の情報をログとして出力する、という現場の言い回し。</p><p><strong>例</strong>　ロードが失敗したら、対象のファイル名と理由をログに吐く。</p><p><strong>関連</strong>　<a href="/study/glossary/programming.html#crash-slang">落ちる</a> · <a href="/study/glossary/programming.html#debugger">デバッガー</a></p><p><strong>出典</strong>　<a href="https://docs.python.org/3/library/logging.html" target="_blank" rel="noreferrer">Python — logging</a></p>',357)])])}const u=t(e,[["render",n]]);export{d as __pageData,u as default};
